import { defineConfig } from "vite";
import solid from "vite-plugin-solid";
import { fileURLToPath } from "node:url";
import { readFileSync } from "node:fs";

// Static marketing pages (/open/, /compare/…, /bn/…) generated by
// `node site/build.mjs`, which lists them in site/inputs.json.
const sitePages: string[] = JSON.parse(readFileSync(new URL("./site/inputs.json", import.meta.url), "utf8"));

export default defineConfig({
  // Served from the domain root: "/" is the website, "/board/" is the app.
  base: "/",
  plugins: [solid()],
  server: {
    port: 3737,
    host: "127.0.0.1",
    fs: { allow: ["../.."] },
    // Smart Objects run in opaque-origin frames (Origin: null); they load
    // /rupoklib/ modules and fonts, which need CORS.
    cors: { origin: "*" },
  },
  preview: { cors: { origin: "*" } },
  build: {
    target: "es2022",
    chunkSizeWarningLimit: 4096,
    rollupOptions: {
      input: {
        site: fileURLToPath(new URL("./index.html", import.meta.url)),
        board: fileURLToPath(new URL("./board/index.html", import.meta.url)),
        ...Object.fromEntries(
          sitePages.map((p) => [p.replace(/\/?index\.html$/, "").replaceAll("/", "-"), fileURLToPath(new URL(`./${p}`, import.meta.url))]),
        ),
      },
    },
  },
  optimizeDeps: { exclude: ["./src/wasm/rupok.js"] },
});
